    func bodyLong() -> some View { font(.appBody).lineSpacing(6) }
}

/// Motion: ease-out for most changes, a light spring for things that appear; no big bounces, no parallax.
enum Motion {
    static let fast = Animation.timingCurve(0.2, 0, 0, 1, duration: 0.16)
    static let standard = Animation.timingCurve(0.2, 0, 0, 1, duration: 0.24)
    static let spring = Animation.timingCurve(0.34, 1.36, 0.64, 1, duration: 0.42)
}

